// TH15 Stage 4 wave card. st04.ecl.txt:1240-1286 MainSub05 (entry),
// 419-454 ECir05 and 456-497 ECir05_at (dependencies).
// Card frame 0 = phase start; 120-frame opening buffer, then source wait(200).
// Source F0=1.570796 (90deg), F1=3.883222 rad (40504 BAM); I0=50 has no reader in this card.

const TIME_LIMIT: int = 2424;
const OPENING_BUFFER: int = 120;
const LASER_COLOR: int = 4;      // etSprite(0,8,4): colour nibble of the Line
const STEP_BAM: int = 40504;     // F1 = 3.883222 rad

// ECir05 (419-454): entrance from REL(-64,-128) quad-out over 60f, then
// flagClear(15), async laser fan, and after 180f a slow drift toward the player.
async sub ecir_main(tx: fx, ty: fx, base: int) {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);   // flagSet(15) carries 0x2 (no body) during entrance
    set_hurtbox(12fx);                  // setHurtbox(24,24): circle branch 24*0.5
    set_hitbox(8fx);                    // setHitbox(16,16): circle branch 16*0.5
    move_to(60, tx, ty, EASE_QUAD_OUT); // movePosRel(-64,-128)+movePosRelTime(60,4,0,0)
    wait(60);
    set_enemy_flag(ENEMY_NO_BODY, 0);   // flagClear(15)
    spawn ecir_at(base, 0);             // @ECir05_at() async, split over 4 lanes
    spawn ecir_at(base, 1);             // to stay inside the per-task instruction budget
    spawn ecir_at(base, 2);
    spawn ecir_at(base, 3);
    wait(180);
    move_angle(0, aim_player(), EASE_LINEAR);   // moveVel(ANGLE_PLAYER,0)
    move_speed(120, 1fx, EASE_LINEAR);          // moveSpeedTime(120,0,1.0)
    loop { wait(1000); }                        // goto 752 -> wait(1000) forever
}

// ECir05_at (456-497): per-enemy golden-angle fan of straight Line lasers.
// Source Line: initial 0 -> target 240, emitter speed 0.4, EX WAIT 60 then
// ACCEL 120 with scalar 0.1 (Easy) / 0.13 (others), angle sentinel keeps beam angle.
// Collision segment is [0.1L,0.9L] while growing, then the 192px rod translates.
// Target: one laser per shot, a fixed 216px far end moved by lz_origin plus a
// per-frame lz_start rebuild of the source near end; warn 40 matches source L>16.
// Four lanes keep each task's per-frame instruction count low; lane q creates
// shot i where i%4==q, so the union keeps the source's one-shot-every-gap cadence.
async sub ecir_at(base: int, lane: int) {
    var n: int = 30;
    var gap: int = 2;
    var acc: fx = 0.1fx;
    if global(GVAR_RANK) != RANK_EASY { n = 60; gap = 1; acc = 0.13fx; }
    var span: int = 4 * gap;
    var ex: fx = $self_x;
    var ey: fx = $self_y;
    var a0: angle = aim_player() + 90deg;   // %A = ANGLE_PLAYER + F0
    var t: int = 0;
    while t < 169 {
        if t % span == lane * gap {
            var idx: int = t / gap;
            if idx < n {
                var a1: angle = a0 - ((idx * STEP_BAM) as angle);   // %A -= F1
                var ca1: fx = cos(a1);
                var sa1: fx = sin(a1);
                // etDist(32) along the beam; at L=0 both ends sit on that point.
                var h1: int = laser(LASER_COLOR, ex + (32fx - 216fx) * ca1, ey + (32fx - 216fx) * sa1,
                                    a1, 216fx, 8fx, 40, 130, 0);
                set_global(base + idx, h1);
                if h1 >= 0 { lz_start(h1, 216fx); }
            }
        }
        var j: int = lane;
        while j <= t / gap {
            if j < n {
                var age: int = t - j * gap;
                if age > 0 {
                    var h2: int = global(base + j);
                    if h2 >= 0 {
                        var len: fx = 0fx;
                        if age <= 60 {
                            len = 0.4fx * age;
                        } else {
                            var d: int = age - 60;
                            len = 24fx + 0.4fx * d + acc * d * d / 2;
                        }
                        var capped: fx = len;
                        if capped > 240fx { capped = 240fx; }
                        var travel: fx = len - capped;
                        var near_src: fx = 0.1fx * capped + travel;
                        var far_src: fx = near_src + 0.8fx * capped;
                        var off: fx = far_src - 216fx;
                        var a2: angle = a0 - ((j * STEP_BAM) as angle);
                        var ca2: fx = cos(a2);
                        var sa2: fx = sin(a2);
                        lz_origin(h2, ex + (32fx + off) * ca2, ey + (32fx + off) * sa2);
                        lz_start(h2, near_src - off);
                    }
                }
            }
            j = j + 4;
        }
        t = t + 1;
        wait(1);
    }
}

// MainSub05 creation schedule (lines 1240-1286). Group spacing 170f;
// rank masks are !L / !HL / !ENH exactly as in the source.
sub spawn_ecir(tx: fx, ty: fx, k: int) {
    var base: int = 16 + (k % 15) * 60;     // free globals block, one slot per laser
    // movePosRel(-64,-128): the enemy starts 64 left / 128 above its final point.
    _ = spawn_enemy(tx - 64fx, ty - 128fx, 400, 0, 1000, 0, ecir_main(tx, ty, base));
}

async sub pattern() {
    wait(OPENING_BUFFER);
    wait(200);                              // source line 1242
    var rank: int = global(GVAR_RANK);
    var k: int = 0;
    spawn_ecir(0fx, 128fx, k); k = k + 1;                       // 1246
    if rank == RANK_LUNATIC { spawn_ecir(128fx, 128fx, k); k = k + 1; }   // 1247-1249
    wait(170);                                                  // 1250
    spawn_ecir(-128fx, 128fx, k); k = k + 1;                    // 1251
    if rank >= RANK_HARD { spawn_ecir(32fx, 128fx, k); k = k + 1; }       // 1252-1254
    wait(170);                                                  // 1255
    spawn_ecir(0fx, 128fx, k); k = k + 1;                       // 1256
    if rank == RANK_LUNATIC { spawn_ecir(-128fx, 128fx, k); k = k + 1; }  // 1257-1259
    wait(170);                                                  // 1260
    spawn_ecir(128fx, 128fx, k); k = k + 1;                     // 1261
    if rank >= RANK_HARD { spawn_ecir(-32fx, 128fx, k); k = k + 1; }      // 1262-1264
    wait(170);                                                  // 1265
    if rank <= RANK_HARD {                                      // !ENH 1266-1267
        spawn_ecir(0fx, 128fx, k); k = k + 1;
    } else {                                                    // !L 1268-1271
        spawn_ecir(32fx, 128fx, k); k = k + 1;
        spawn_ecir(-32fx, 128fx, k); k = k + 1;
    }
    wait(170);                                                  // 1272
    spawn_ecir(128fx, 128fx, k); k = k + 1;                     // 1273
    spawn_ecir(-128fx, 128fx, k); k = k + 1;                    // 1274
    wait(170);                                                  // 1275
    spawn_ecir(160fx, 128fx, k); k = k + 1;                     // 1276
    if rank <= RANK_HARD {                                      // !ENH 1277-1278
        spawn_ecir(0fx, 128fx, k); k = k + 1;
    } else {                                                    // !L 1279-1282
        spawn_ecir(32fx, 64fx, k); k = k + 1;
        spawn_ecir(-32fx, 64fx, k); k = k + 1;
    }
    spawn_ecir(-160fx, 128fx, k); k = k + 1;                    // 1283
    wait(170);                                                  // 1284
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
